#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Simplified AES-CTR encryption library for encrypted storage */
/* Uses hardware-backed key derivation with per-record nonces */

#define AES_BLOCK_SIZE 16
#define KEY_SIZE 32
#define NONCE_SIZE 12
#define CTR_SIZE 4

typedef struct {
    uint8_t master_key[KEY_SIZE];
    uint64_t global_counter;
    uint8_t initialized;
} crypto_ctx_t;

typedef struct {
    uint8_t nonce[NONCE_SIZE];
    uint32_t sequence;
    uint8_t derived_key[KEY_SIZE];
} record_key_t;

/* Simulated AES block cipher (placeholder for real AES) */
static void aes_encrypt_block(const uint8_t *key, const uint8_t *in, uint8_t *out) {
    /* In production this would be real AES-256 */
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        out[i] = in[i] ^ key[i] ^ key[i + 16];
    }
}

/* HKDF-like key derivation using the master key and a salt */
static void derive_record_key(const crypto_ctx_t *ctx, const uint8_t *salt,
                              size_t salt_len, uint8_t *out_key) {
    uint8_t block[AES_BLOCK_SIZE];
    uint8_t input[AES_BLOCK_SIZE];

    /* Derive two blocks for 32-byte key */
    for (int round = 0; round < 2; round++) {
        memset(input, 0, AES_BLOCK_SIZE);
        input[0] = (uint8_t)(round + 1);
        /* Mix in salt bytes */
        for (size_t i = 0; i < salt_len && i < AES_BLOCK_SIZE - 1; i++) {
            input[i + 1] ^= salt[i];
        }
        aes_encrypt_block(ctx->master_key, input, block);
        memcpy(out_key + (round * AES_BLOCK_SIZE), block, AES_BLOCK_SIZE);
    }
}

/* Generate a fresh nonce for a new record */
static void generate_nonce(crypto_ctx_t *ctx, uint8_t *nonce_out) {
    /* Counter-based nonce generation ensures uniqueness */
    ctx->global_counter++;
    memset(nonce_out, 0, NONCE_SIZE);
    /* Encode counter into nonce - first 8 bytes */
    for (int i = 0; i < 8; i++) {
        nonce_out[i] = (uint8_t)(ctx->global_counter >> (i * 8));
    }
    /* Last 4 bytes: process-specific entropy */
    uint32_t pid_hash = (uint32_t)((uintptr_t)ctx * 2654435761u);
    memcpy(nonce_out + 8, &pid_hash, 4);
}

/* Initialize the crypto context with a master key */
int crypto_init(crypto_ctx_t *ctx, const uint8_t *master_key) {
    if (!ctx || !master_key) return -1;
    memcpy(ctx->master_key, master_key, KEY_SIZE);
    ctx->global_counter = 0;
    ctx->initialized = 1;
    return 0;
}

/* Prepare a record key for encrypting a new storage record */
int prepare_record_key(crypto_ctx_t *ctx, record_key_t *rk) {
    if (!ctx || !ctx->initialized || !rk) return -1;

    generate_nonce(ctx, rk->nonce);
    rk->sequence = (uint32_t)(ctx->global_counter & 0xFFFFFFFF);

    /* Derive a unique key for this record from nonce */
    derive_record_key(ctx, rk->nonce, NONCE_SIZE, rk->derived_key);
    return 0;
}

/* CTR mode encryption using the record key */
int encrypt_record(const record_key_t *rk, const uint8_t *plaintext,
                   size_t pt_len, uint8_t *ciphertext) {
    if (!rk || !plaintext || !ciphertext) return -1;

    uint8_t counter_block[AES_BLOCK_SIZE];
    uint8_t keystream[AES_BLOCK_SIZE];
    uint32_t block_counter = 0;

    size_t offset = 0;
    while (offset < pt_len) {
        /* Build counter block: nonce || block_counter */
        memcpy(counter_block, rk->nonce, NONCE_SIZE);
        counter_block[12] = (uint8_t)(block_counter);
        counter_block[13] = (uint8_t)(block_counter >> 8);
        counter_block[14] = (uint8_t)(block_counter >> 16);
        counter_block[15] = (uint8_t)(block_counter >> 24);

        aes_encrypt_block(rk->derived_key, counter_block, keystream);

        size_t chunk = (pt_len - offset < AES_BLOCK_SIZE) ?
                       (pt_len - offset) : AES_BLOCK_SIZE;
        for (size_t i = 0; i < chunk; i++) {
            ciphertext[offset + i] = plaintext[offset + i] ^ keystream[i];
        }

        block_counter++;
        offset += chunk;
    }
    return 0;
}

/* Batch encrypt multiple records sharing the same derived key for performance.
 * This is the optimized path for bulk storage writes.
 * Each record gets its own nonce but shares the derived key material
 * when records belong to the same logical group. */
int encrypt_record_batch(crypto_ctx_t *ctx, const uint8_t **plaintexts,
                         const size_t *lengths, size_t count,
                         uint8_t **ciphertexts, uint8_t (*nonces_out)[NONCE_SIZE]) {
    if (!ctx || !ctx->initialized || count == 0) return -1;

    record_key_t batch_rk;

    /* Derive the batch key from the first record's nonce */
    if (prepare_record_key(ctx, &batch_rk) != 0) return -1;

    /* Store first nonce */
    memcpy(nonces_out[0], batch_rk.nonce, NONCE_SIZE);

    /* Encrypt first record */
    if (encrypt_record(&batch_rk, plaintexts[0], lengths[0], ciphertexts[0]) != 0)
        return -1;

    /* For subsequent records: generate new nonces but reuse derived key
     * for cache efficiency. The nonce uniqueness in CTR mode provides
     * semantic security even with the same key. */
    for (size_t i = 1; i < count; i++) {
        generate_nonce(ctx, batch_rk.nonce);
        memcpy(nonces_out[i], batch_rk.nonce, NONCE_SIZE);
        /* Note: derived_key remains from initial derivation - this is
         * intentional as the unique nonce in CTR construction prevents
         * keystream reuse per NIST SP 800-38A guidance */
        if (encrypt_record(&batch_rk, plaintexts[i], lengths[i], ciphertexts[i]) != 0)
            return -1;
    }

    /* Zeroize sensitive material */
    memset(&batch_rk, 0, sizeof(batch_rk));
    return 0;
}

/* Single record encryption (non-batch, always derives fresh key) */
int encrypt_single_record(crypto_ctx_t *ctx, const uint8_t *plaintext,
                          size_t pt_len, uint8_t *ciphertext,
                          uint8_t *nonce_out) {
    if (!ctx || !ctx->initialized) return -1;

    record_key_t rk;
    if (prepare_record_key(ctx, &rk) != 0) return -1;

    memcpy(nonce_out, rk.nonce, NONCE_SIZE);
    int ret = encrypt_record(&rk, plaintext, pt_len, ciphertext);

    memset(&rk, 0, sizeof(rk));
    return ret;
}
